import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"Referência de comandos CLI","description":"","frontmatter":{"title":"Referência de comandos CLI","docId":"developer.cli","translationKey":"developer.cli","locale":"pt","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6bb485d6e8067cb1639fb20821c45b79941245692f0b6c7525f2b3bee930048b","translationRevision":"5922b8bff2a025a8a5f3b9255d27787f5de6e367a3026e016c6f2db98e9af959","order":75},"headers":[],"relativePath":"pt/developer/cli.md","filePath":"pt/developer/cli.md","lastUpdated":1795727787000}`),a={name:`pt/developer/cli.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="cli-command-reference" tabindex="-1">Referência de comandos CLI <a class="header-anchor" href="#cli-command-reference" aria-label="Permalink to “Referência de comandos CLI”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo e pré-requisitos”">​</a></h2><p>Descubra cada forma de comando <code>tiktools</code> sem ler o código Rust nem analisar a saída de ajuda humana. Tenha um binário <code>tiktools</code> correspondente compilado; a referência é offline e nunca precisa de um host ativo. A fonte canônica é o registro de especificações em <code>crates/tiktools-cli/src/commands/spec.rs</code>; cada módulo de domínio possui as cadeias de uso que seu parser reporta em erros, portanto esta referência não pode divergir do que o parser aceita.</p><h2 id="inspect-help-offline" tabindex="-1">Inspecionar a ajuda offline <a class="header-anchor" href="#inspect-help-offline" aria-label="Permalink to “Inspecionar a ajuda offline”">​</a></h2><p>A ajuda humana agrupa os verbos por domínio; o filtro mostra uma seção de domínio. A forma <code>--json</code> imprime o registro legível por máquina que todo agente deveria preferir: uso, resumo e marcador destrutivo por verbo, mais as convenções globais da CLI, versionado pelo campo <code>schema</code> superior.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>Erros de uso imprimem apenas a forma relevante com uma dica em vez da página completa, então um erro de digitação nunca rola o terminal. O código de saída 2 sempre significa erro de uso; consulte o rodapé de convenções para as regras de resolução do host, saída e redação de segredos.</p><h2 id="generated-command-reference" tabindex="-1">Referência de comandos gerada <a class="header-anchor" href="#generated-command-reference" aria-label="Permalink to “Referência de comandos gerada”">​</a></h2><p>Gerada a partir do instantâneo de ajuda CLI versionado em <code>docs/contracts/cli-help.json</code>; o binário continua sendo a autoridade. As linhas de uso são sintaxe do parser e permanecem em inglês em todas as localidades; os resumos e convenções vêm dos catálogos de tradução da própria CLI, portanto esta referência não pode divergir do que <code>tiktools help</code> imprime no mesmo idioma. Os verbos marcados como destrutivos mutam ou destroem estado; scripts deveriam confirmar antes de executá-los.</p><p><code>tiktools [--json] [--standalone] &lt;command&gt; [args]</code></p><h3 id="tiktools-plugin-—-instalar-e-gerenciar-plugins" tabindex="-1"><code>tiktools plugin</code> — instalar e gerenciar plugins <a class="header-anchor" href="#tiktools-plugin-—-instalar-e-gerenciar-plugins" aria-label="Permalink to “tiktools plugin — instalar e gerenciar plugins”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools plugin list</code></td><td>listar os plugins instalados</td></tr><tr><td><code>tiktools plugin get &lt;id&gt;</code></td><td>ler um plugin</td></tr><tr><td><code>tiktools plugin install &lt;file.plugin&gt; [--replace] &amp;#124; plugin install &lt;id[@version]&amp;#124;url&gt; [--yes] [--no-wait] [--allow-unsigned]</code></td><td>instalar a partir de um arquivo, id@version ou url</td></tr><tr><td><code>tiktools plugin uninstall &lt;id&gt; [--purge]</code></td><td>desinstalar um plugin <strong>destrutivo</strong></td></tr><tr><td><code>tiktools plugin search &lt;query&gt; [--category c] [--page N]</code></td><td>buscar pacotes no registro</td></tr><tr><td><code>tiktools plugin inspect &lt;spec&gt;</code></td><td>inspecionar uma especificação de pacote antes de instalar</td></tr><tr><td><code>tiktools plugin outdated</code></td><td>listar os plugins instalados com atualizações disponíveis</td></tr><tr><td><code>tiktools plugin update &lt;id&gt; [--version v] [--yes] [--no-wait]</code></td><td>atualizar um plugin</td></tr><tr><td><code>tiktools plugin update --all [--yes] [--no-wait]</code></td><td>atualizar todos os plugins desatualizados</td></tr><tr><td><code>tiktools plugin rollback &lt;id&gt; [version] [--no-wait]</code></td><td>voltar a uma versão anterior <strong>destrutivo</strong></td></tr><tr><td><code>tiktools plugin versions &lt;id&gt;</code></td><td>listar as versões disponíveis de um plugin</td></tr><tr><td><code>tiktools plugin pin &lt;id&gt;</code></td><td>fixar um plugin na sua versão atual</td></tr><tr><td><code>tiktools plugin unpin &lt;id&gt;</code></td><td>remover a fixação de versão</td></tr><tr><td><code>tiktools plugin policy &lt;id&gt; [--channel stable&amp;#124;beta] [--auto off&amp;#124;notify&amp;#124;patch&amp;#124;minor]</code></td><td>definir o canal e a política de atualização automática</td></tr><tr><td><code>tiktools plugin jobs</code></td><td>listar os trabalhos de pacotes</td></tr><tr><td><code>tiktools plugin job &lt;job-id&gt;</code></td><td>inspecionar um trabalho de pacote</td></tr><tr><td><code>tiktools plugin cancel &lt;job-id&gt;</code></td><td>cancelar um trabalho de pacote em andamento <strong>destrutivo</strong></td></tr><tr><td><code>tiktools plugin enable &lt;id&gt;</code></td><td>ativar um plugin</td></tr><tr><td><code>tiktools plugin disable &lt;id&gt;</code></td><td>desativar um plugin</td></tr><tr><td><code>tiktools plugin start &lt;id&gt;</code></td><td>iniciar um plugin</td></tr><tr><td><code>tiktools plugin stop &lt;id&gt;</code></td><td>parar um plugin <strong>destrutivo</strong></td></tr><tr><td><code>tiktools plugin settings get &lt;id&gt;</code></td><td>ler a configuração de um plugin</td></tr><tr><td><code>tiktools plugin settings set &lt;id&gt; k=v...</code></td><td>escrever a configuração de um plugin</td></tr><tr><td><code>tiktools plugin settings reset &lt;id&gt;</code></td><td>redefinir a configuração de um plugin <strong>destrutivo</strong></td></tr><tr><td><code>tiktools plugin health &lt;id&gt;</code></td><td>verificação de saúde de um plugin</td></tr><tr><td><code>tiktools plugin options &lt;action-type/field&gt;</code></td><td>opções de um tipo de ação ou campo</td></tr><tr><td><code>tiktools plugin action &lt;type&gt; [--config json] [--live]</code></td><td>executar uma ação de plugin</td></tr><tr><td><code>tiktools plugin commands</code></td><td>listar os comandos contribuídos pelos plugins instalados</td></tr><tr><td><code>tiktools plugin help [id]</code></td><td>descrever um comando contribuído</td></tr><tr><td><code>tiktools plugin &lt;id&gt; &lt;command&gt; [--params json] [--live]</code></td><td>invocar um comando contribuído por um plugin</td></tr></tbody></table><h3 id="tiktools-cloud-—-conta-cloud-e-backup-restauracao-portatil-sobrescreva-com-tiktools-cloud-origin" tabindex="-1"><code>tiktools cloud</code> — conta cloud e backup/restauração portátil (sobrescreva com TIKTOOLS_CLOUD_ORIGIN) <a class="header-anchor" href="#tiktools-cloud-—-conta-cloud-e-backup-restauracao-portatil-sobrescreva-com-tiktools-cloud-origin" aria-label="Permalink to “tiktools cloud — conta cloud e backup/restauração portátil (sobrescreva com TIKTOOLS_CLOUD_ORIGIN)”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools cloud status</code></td><td>estado da conta cloud</td></tr><tr><td><code>tiktools cloud login</code></td><td>entrar pelo navegador do sistema</td></tr><tr><td><code>tiktools cloud logout</code></td><td>sair da conta <strong>destrutivo</strong></td></tr><tr><td><code>tiktools cloud restore</code></td><td>restaurar a sessão cloud</td></tr><tr><td><code>tiktools cloud backup create [--out FILE]</code></td><td>escrever um arquivo de backup portátil</td></tr><tr><td><code>tiktools cloud backup preview &lt;file&gt;</code></td><td>inspecionar um arquivo de backup</td></tr><tr><td><code>tiktools cloud backup restore &lt;file&gt; [--yes]</code></td><td>restaurar um arquivo de backup <strong>destrutivo</strong></td></tr></tbody></table><h3 id="tiktools-publisher-—-fluxo-de-publicador-cloud-requer-login" tabindex="-1"><code>tiktools publisher</code> — fluxo de publicador cloud (requer login) <a class="header-anchor" href="#tiktools-publisher-—-fluxo-de-publicador-cloud-requer-login" aria-label="Permalink to “tiktools publisher — fluxo de publicador cloud (requer login)”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools publisher list</code></td><td>listar os namespaces de publicador</td></tr><tr><td><code>tiktools publisher create &lt;namespace&gt;</code></td><td>criar um namespace de publicador</td></tr><tr><td><code>tiktools publisher delete &lt;namespace-or-publisher-id&gt;</code></td><td>excluir um namespace ou publicador <strong>destrutivo</strong></td></tr><tr><td><code>tiktools publisher keys &lt;publisher-id&gt;</code></td><td>listar as chaves de assinatura de um publicador</td></tr><tr><td><code>tiktools publisher enroll &lt;publisher-id&gt; [--key-id &lt;id&gt;]</code></td><td>inscrever uma chave de publicador; lê a senha do backend a partir de stdin</td></tr><tr><td><code>tiktools publisher upload &lt;publisher-id&gt; &lt;path&gt;</code></td><td>enviar um pacote de plugin</td></tr><tr><td><code>tiktools publisher submit &lt;upload-id&gt; &lt;publisher-key-id&gt; &lt;plugin-id&gt; &lt;version&gt; [--target any]</code></td><td>submeter um envio para revisão</td></tr><tr><td><code>tiktools publisher release &lt;release-id&gt;</code></td><td>criar uma release</td></tr><tr><td><code>tiktools publisher publish &lt;release-id&gt;</code></td><td>publicar uma release</td></tr></tbody></table><h3 id="tiktools-registry-—-registros-de-pacotes-e-o-catalogo-cloud" tabindex="-1"><code>tiktools registry</code> — registros de pacotes e o catálogo cloud <a class="header-anchor" href="#tiktools-registry-—-registros-de-pacotes-e-o-catalogo-cloud" aria-label="Permalink to “tiktools registry — registros de pacotes e o catálogo cloud”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools registry list</code></td><td>listar os registros configurados</td></tr><tr><td><code>tiktools registry refresh</code></td><td>atualizar os metadados do registro</td></tr><tr><td><code>tiktools registry package &lt;id&gt;</code></td><td>mostrar um pacote do registro</td></tr><tr><td><code>tiktools registry cloud-catalog [--query q] [--after cursor] [--generation value] [--target name]</code></td><td>buscar no catálogo cloud</td></tr><tr><td><code>tiktools registry cloud-summaries [--query q] [--cursor value] [--generation value] [--target name]</code></td><td>página de resumos do catálogo cloud</td></tr><tr><td><code>tiktools registry cloud-versions &lt;id&gt; [--target name] [--generation value] [--cursor value]</code></td><td>versões de um pacote do catálogo cloud</td></tr><tr><td><code>tiktools registry cloud-pagination</code></td><td>capacidades de paginação do catálogo cloud</td></tr><tr><td><code>tiktools registry defaults</code></td><td>configuração padrão do registro</td></tr></tbody></table><h3 id="tiktools-processor-—-processadores-de-eventos" tabindex="-1"><code>tiktools processor</code> — processadores de eventos <a class="header-anchor" href="#tiktools-processor-—-processadores-de-eventos" aria-label="Permalink to “tiktools processor — processadores de eventos”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools processor list</code></td><td>listar os processadores</td></tr><tr><td><code>tiktools processor status</code></td><td>estado do pipeline de processadores</td></tr><tr><td><code>tiktools processor test &lt;plugin-id&gt; &lt;processor-id&gt; [event-json]</code></td><td>executar um processador contra um evento de amostra</td></tr></tbody></table><h3 id="tiktools-live-—-conexao-com-tiktok-live" tabindex="-1"><code>tiktools live</code> — conexão com TikTok LIVE <a class="header-anchor" href="#tiktools-live-—-conexao-com-tiktok-live" aria-label="Permalink to “tiktools live — conexão com TikTok LIVE”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools live connect --unique-id &lt;id&gt; --session-cookie &lt;cookie&gt; [--room-id &lt;id&gt;]</code></td><td>conectar a uma sala ao vivo</td></tr><tr><td><code>tiktools live pick --session-cookie &lt;cookie&gt;</code></td><td>escolher uma sala ao vivo interativamente</td></tr><tr><td><code>tiktools live channels [--keyword text] [--offset N] [--limit N] [--session-cookie &lt;cookie&gt;]</code></td><td>descobrir canais ao vivo; funciona sem sessão</td></tr><tr><td><code>tiktools live disconnect</code></td><td>desconectar da sala atual <strong>destrutivo</strong></td></tr><tr><td><code>tiktools live status</code></td><td>estado atual da conexão</td></tr></tbody></table><h3 id="tiktools-points-—-pontos-de-fidelidade-de-espectadores" tabindex="-1"><code>tiktools points</code> — pontos de fidelidade de espectadores <a class="header-anchor" href="#tiktools-points-—-pontos-de-fidelidade-de-espectadores" aria-label="Permalink to “tiktools points — pontos de fidelidade de espectadores”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools points config get</code></td><td>ler a configuração de pontos</td></tr><tr><td><code>tiktools points config set k=v...</code></td><td>atualizar a configuração de pontos</td></tr><tr><td><code>tiktools points viewer get &lt;id&gt;</code></td><td>ler o saldo de um espectador</td></tr><tr><td><code>tiktools points adjust &lt;id&gt; &lt;delta&gt;</code></td><td>somar ou subtrair pontos de um espectador</td></tr><tr><td><code>tiktools points leaderboard [--limit N]</code></td><td>espectadores com maior saldo</td></tr><tr><td><code>tiktools points reset [id]</code></td><td>redefinir o saldo de um espectador ou de todos <strong>destrutivo</strong></td></tr></tbody></table><h3 id="tiktools-ranking-—-definicoes-e-estado-de-rankings-de-espectadores" tabindex="-1"><code>tiktools ranking</code> — definições e estado de rankings de espectadores <a class="header-anchor" href="#tiktools-ranking-—-definicoes-e-estado-de-rankings-de-espectadores" aria-label="Permalink to “tiktools ranking — definições e estado de rankings de espectadores”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools ranking list</code></td><td>listar as definições de ranking</td></tr><tr><td><code>tiktools ranking metrics</code></td><td>métricas disponíveis para as definições de ranking</td></tr><tr><td><code>tiktools ranking create --record &lt;json&amp;#124;@file&gt;</code></td><td>criar uma definição de ranking</td></tr><tr><td><code>tiktools ranking update --record &lt;json&amp;#124;@file&gt;</code></td><td>atualizar uma definição de ranking</td></tr><tr><td><code>tiktools ranking get &lt;id&gt;</code></td><td>ler um ranking</td></tr><tr><td><code>tiktools ranking snapshot &lt;id&gt;</code></td><td>classificação atual de um ranking</td></tr><tr><td><code>tiktools ranking delete &lt;id&gt;</code></td><td>excluir um ranking <strong>destrutivo</strong></td></tr><tr><td><code>tiktools ranking reset &lt;id&gt;</code></td><td>redefinir o estado acumulado <strong>destrutivo</strong></td></tr><tr><td><code>tiktools ranking pause &lt;id&gt;</code></td><td>pausar a acumulação</td></tr><tr><td><code>tiktools ranking resume &lt;id&gt;</code></td><td>retomar a acumulação</td></tr><tr><td><code>tiktools ranking contribute --record &lt;json&amp;#124;@file&gt;</code></td><td>adicionar uma contribuição externa</td></tr></tbody></table><h3 id="tiktools-competition-—-competicoes-cronometradas-de-espectadores" tabindex="-1"><code>tiktools competition</code> — competições cronometradas de espectadores <a class="header-anchor" href="#tiktools-competition-—-competicoes-cronometradas-de-espectadores" aria-label="Permalink to “tiktools competition — competições cronometradas de espectadores”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools competition list</code></td><td>listar as competições</td></tr><tr><td><code>tiktools competition get &lt;id&gt;</code></td><td>ler uma competição</td></tr><tr><td><code>tiktools competition create --record &lt;json&amp;#124;@file&gt;</code></td><td>criar uma competição</td></tr><tr><td><code>tiktools competition update --record &lt;json&amp;#124;@file&gt;</code></td><td>atualizar uma competição</td></tr><tr><td><code>tiktools competition delete &lt;id&gt;</code></td><td>excluir uma competição <strong>destrutivo</strong></td></tr><tr><td><code>tiktools competition state &lt;id&gt;</code></td><td>estado atual da competição</td></tr><tr><td><code>tiktools competition results &lt;id&gt;</code></td><td>resultados finais ou intermediários</td></tr><tr><td><code>tiktools competition action --record &lt;json&amp;#124;@file&gt;</code></td><td>registrar uma ação de competição</td></tr><tr><td><code>tiktools competition mark-action-uncertain --record &lt;json&amp;#124;@file&gt;</code></td><td>marcar uma ação como incerta</td></tr><tr><td><code>tiktools competition resolve-action --record &lt;json&amp;#124;@file&gt;</code></td><td>resolver uma ação incerta</td></tr><tr><td><code>tiktools competition start &lt;id&gt;</code></td><td>iniciar uma competição</td></tr><tr><td><code>tiktools competition finish &lt;id&gt;</code></td><td>finalizar uma competição <strong>destrutivo</strong></td></tr><tr><td><code>tiktools competition candidates &lt;id&gt;</code></td><td>candidatos a vencedor</td></tr><tr><td><code>tiktools competition select-winner --record &lt;json&amp;#124;@file&gt;</code></td><td>selecionar o vencedor</td></tr><tr><td><code>tiktools competition pause &lt;id&gt;</code></td><td>pausar uma competição</td></tr><tr><td><code>tiktools competition resume &lt;id&gt;</code></td><td>retomar uma competição</td></tr><tr><td><code>tiktools competition cancel &lt;id&gt;</code></td><td>cancelar uma competição <strong>destrutivo</strong></td></tr></tbody></table><h3 id="tiktools-automation-—-regras-de-automacao-de-eventos-e-acoes" tabindex="-1"><code>tiktools automation</code> — regras de automação de eventos e ações <a class="header-anchor" href="#tiktools-automation-—-regras-de-automacao-de-eventos-e-acoes" aria-label="Permalink to “tiktools automation — regras de automação de eventos e ações”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools automation list [--kind event&amp;#124;action&amp;#124;all]</code></td><td>listar as regras de automação</td></tr><tr><td><code>tiktools automation context [--event-type t]</code></td><td>contexto de modelo disponível para as regras</td></tr><tr><td><code>tiktools automation get &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>ler uma regra</td></tr><tr><td><code>tiktools automation create --record json [--kind event&amp;#124;action]</code></td><td>criar uma regra</td></tr><tr><td><code>tiktools automation update &lt;id&gt; --record json [--kind event&amp;#124;action]</code></td><td>atualizar uma regra</td></tr><tr><td><code>tiktools automation delete &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>excluir uma regra <strong>destrutivo</strong></td></tr><tr><td><code>tiktools automation enable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>ativar uma regra</td></tr><tr><td><code>tiktools automation disable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>desativar uma regra</td></tr><tr><td><code>tiktools automation test (--id &lt;id&gt; &amp;#124; --record json) [--kind event&amp;#124;action] [--trigger t] [--event json]</code></td><td>testar uma regra em seco contra um evento de amostra</td></tr><tr><td><code>tiktools automation fire --trigger &lt;type&gt; [--event json] [--record json]</code></td><td>disparar um gatilho manualmente</td></tr><tr><td><code>tiktools automation moderation-penalty --points &lt;delta&gt;</code></td><td>aplicar uma penalidade de moderação em pontos</td></tr></tbody></table><h3 id="tiktools-globals-—-globais-chave-valor-compartilhados-entre-plugins" tabindex="-1"><code>tiktools globals</code> — globais chave/valor compartilhados entre plugins <a class="header-anchor" href="#tiktools-globals-—-globais-chave-valor-compartilhados-entre-plugins" aria-label="Permalink to “tiktools globals — globais chave/valor compartilhados entre plugins”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools globals list</code></td><td>listar todas as chaves globais</td></tr><tr><td><code>tiktools globals get &lt;key&gt;</code></td><td>ler um global</td></tr><tr><td><code>tiktools globals set &lt;key&gt; &lt;value&gt;</code></td><td>escrever um global</td></tr><tr><td><code>tiktools globals delete &lt;key&gt;</code></td><td>excluir um global <strong>destrutivo</strong></td></tr></tbody></table><h3 id="tiktools-workflow-—-grafos-de-workflows-visuais" tabindex="-1"><code>tiktools workflow</code> — grafos de workflows visuais <a class="header-anchor" href="#tiktools-workflow-—-grafos-de-workflows-visuais" aria-label="Permalink to “tiktools workflow — grafos de workflows visuais”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools workflow list</code></td><td>listar os grafos de workflow salvos</td></tr><tr><td><code>tiktools workflow get &lt;id&gt;</code></td><td>ler um grafo</td></tr><tr><td><code>tiktools workflow save --record json</code></td><td>criar ou substituir um grafo</td></tr><tr><td><code>tiktools workflow delete &lt;id&gt;</code></td><td>excluir um grafo <strong>destrutivo</strong></td></tr><tr><td><code>tiktools workflow enable &lt;id&gt;</code></td><td>ativar um grafo</td></tr><tr><td><code>tiktools workflow disable &lt;id&gt;</code></td><td>desativar um grafo</td></tr></tbody></table><h3 id="tiktools-media-—-validacao-e-reproducao-de-arquivos-de-midia" tabindex="-1"><code>tiktools media</code> — validação e reprodução de arquivos de mídia <a class="header-anchor" href="#tiktools-media-—-validacao-e-reproducao-de-arquivos-de-midia" aria-label="Permalink to “tiktools media — validação e reprodução de arquivos de mídia”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools media validate &lt;path&gt; [--kind audio&amp;#124;video&amp;#124;image&amp;#124;other]</code></td><td>validar um arquivo de mídia antes de usá-lo em ações</td></tr></tbody></table><h3 id="tiktools-system-—-informacao-e-diagnostico-do-host" tabindex="-1"><code>tiktools system</code> — informação e diagnóstico do host <a class="header-anchor" href="#tiktools-system-—-informacao-e-diagnostico-do-host" aria-label="Permalink to “tiktools system — informação e diagnóstico do host”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools system info</code></td><td>versão do host e informação do runtime</td></tr><tr><td><code>tiktools system health</code></td><td>relatório de saúde dos componentes</td></tr><tr><td><code>tiktools system snapshot</code></td><td>instantâneo completo do estado para depuração</td></tr><tr><td><code>tiktools system doctor</code></td><td>diagnosticar problemas comuns de configuração</td></tr><tr><td><code>tiktools system request-input-access</code></td><td>pedir acesso de entrada ao usuário do desktop</td></tr><tr><td><code>tiktools system shutdown</code></td><td>desligar o host em execução <strong>destrutivo</strong></td></tr></tbody></table><h3 id="tiktools-template-—-modelos-de-automacao-e-perfis-reutilizaveis" tabindex="-1"><code>tiktools template</code> — modelos de automação e perfis reutilizáveis <a class="header-anchor" href="#tiktools-template-—-modelos-de-automacao-e-perfis-reutilizaveis" aria-label="Permalink to “tiktools template — modelos de automação e perfis reutilizáveis”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools template import &lt;file&gt; [--param k=v]... [--event-name n] [--action-name n] [--dry-run] [--no-save] [--disabled]</code></td><td>importar um modelo como regras de automação</td></tr><tr><td><code>tiktools template export --event &lt;id&gt; --out &lt;file&gt; [--title t] [--id template-id]</code></td><td>exportar uma regra de eventos como modelo</td></tr><tr><td><code>tiktools template list</code></td><td>listar os modelos da galeria</td></tr><tr><td><code>tiktools template delete &lt;template-id&gt;</code></td><td>excluir um modelo <strong>destrutivo</strong></td></tr><tr><td><code>tiktools template profile-import &lt;file&gt; [--param k=v]... [--dry-run] [--no-save] [--disabled]</code></td><td>importar um perfil de automação completo</td></tr><tr><td><code>tiktools template profile-export --out &lt;file&gt; [--name n]</code></td><td>exportar o perfil de automação</td></tr></tbody></table><h3 id="tiktools-api-—-superficie-de-controle-generica-orientada-a-agentes-sobre-os-metodos-do-host" tabindex="-1"><code>tiktools api</code> — superfície de controle genérica orientada a agentes sobre os métodos do host <a class="header-anchor" href="#tiktools-api-—-superficie-de-controle-generica-orientada-a-agentes-sobre-os-metodos-do-host" aria-label="Permalink to “tiktools api — superfície de controle genérica orientada a agentes sobre os métodos do host”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools api discover [--format json&amp;#124;human]</code></td><td>listar todos os métodos ao vivo do registro do host</td></tr><tr><td><code>tiktools api schema &lt;method&gt; [--format json&amp;#124;human]</code></td><td>descrição, flags e esquemas de um método</td></tr><tr><td><code>tiktools api call &lt;method&gt; [params-json] [--timeout SEC] [--dry-run] [--confirm] [--redact&amp;#124;--secrets-visible] [--explain] [--format json&amp;#124;human] [--expected-revision N] [--command-id ID --host-instance-id ID] [--include-meta]</code></td><td>validar e executar um método; os destrutivos precisam de --confirm</td></tr><tr><td><code>tiktools api events [--topics t,...] [--timeout SEC] [--max-events N]</code></td><td>transmitir eventos de domínio NDJSON</td></tr><tr><td><code>tiktools api event get &lt;name&gt; [--type kind]... [--author text] [--limit N]</code></td><td>buscar no diário limitado do feed</td></tr><tr><td><code>tiktools api verify [--coverage&amp;#124;--smoke] [--sandbox] [--timeout SEC]</code></td><td>verificar a superfície de controle contra o host</td></tr></tbody></table><h3 id="tiktools-host-—-runtimes-de-host-sem-interface-e-a-passagem-direta-de-rpc" tabindex="-1"><code>tiktools host</code> — runtimes de host sem interface e a passagem direta de rpc <a class="header-anchor" href="#tiktools-host-—-runtimes-de-host-sem-interface-e-a-passagem-direta-de-rpc" aria-label="Permalink to “tiktools host — runtimes de host sem interface e a passagem direta de rpc”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools host --stdio [--events]</code></td><td>host sem interface em stdio; transmite eventos com --events</td></tr><tr><td><code>tiktools host --ipc</code></td><td>host sem interface em IPC local; recusa quando já há um host em execução</td></tr><tr><td><code>tiktools rpc &lt;method&gt; [params-json] &amp;#124; rpc --stdio [--events]</code></td><td>passagem direta sem tipos para qualquer método do host</td></tr><tr><td><code>tiktools rpc --stdio [--events]</code></td><td>laço de requisição/resposta NDJSON em stdio</td></tr></tbody></table><h3 id="tiktools-web-—-adaptador-de-navegador-local-requer-a-feature-local-web" tabindex="-1"><code>tiktools web</code> — adaptador de navegador local (requer a feature local-web) <a class="header-anchor" href="#tiktools-web-—-adaptador-de-navegador-local-requer-a-feature-local-web" aria-label="Permalink to “tiktools web — adaptador de navegador local (requer a feature local-web)”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools web --assets &lt;directory&gt; [--port N] [--join-origin URL] [--multi-session]</code></td><td>servir o adaptador de navegador local; host --ipc deve estar em execução</td></tr><tr><td><code>tiktools web --print-code [--port N]</code></td><td>imprimir o código de pareamento ativo sem reiniciar</td></tr><tr><td><code>tiktools web --reset-session [--port N]</code></td><td>revogar todos os navegadores pareados e imprimir um código novo <strong>destrutivo</strong></td></tr></tbody></table><h3 id="convencoes" tabindex="-1">Convenções <a class="header-anchor" href="#convencoes" aria-label="Permalink to “Convenções”">​</a></h3><ul><li><strong>resolução do host</strong>: os comandos executam contra o host em execução por IPC local; quando não há um host ativo falham com host_unavailable em vez de iniciar um segundo runtime. Use <code>tiktools --json system info</code> como sonda leve: saída 0 significa que um host respondeu, saída 3 que o host IPC não está disponível. --standalone executa o comando contra um runtime isolado em processo.</li><li><strong>saída</strong>: stdout carrega o resultado; os diagnósticos vão para stderr. --json imprime o objeto de resultado cru; sem ele, listas imprimem uma linha por item. Valores json podem usar @path para ler de um arquivo. A ajuda humana segue o locale de exibição: TIKTOOLS_LANG sobrescreve a cadeia LC_ALL/LC_MESSAGES/LANG, e a saída de máquina permanece independente do locale.</li><li><strong>códigos de saída</strong>: 0 ok, 1 erro de operação, 2 erro de uso, 3 falha de transporte.</li><li><strong>segredos</strong>: live connect/pick leem o cookie de sessão de --session-cookie ou da variável de ambiente TIKTOOLS_SESSION_COOKIE (o flag vence); o valor nunca aparece nos diagnósticos. api call oculta os segredos da sua saída salvo que se passe --secrets-visible, e recusa métodos destrutivos sem --confirm.</li></ul><h2 id="operational-details" tabindex="-1">Detalhes operacionais <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Detalhes operacionais”">​</a></h2><p>O instantâneo regenera a partir de um binário compilado com <code>--features local-web</code> para que os domínios condicionados por features (cloud, publisher, web) estejam completos. A verificação de proveniência em <code>docs check</code> compara hashes de cada fonte Rust, então qualquer mudança nas especificações de comandos falha a compilação até regenerar o contrato. As compilações normais de documentação nunca executam Cargo.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/scripts/regenerate-control.ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/scripts/generate-references.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/scripts/cli-coverage.ts</span></span></code></pre></div><p>Execute a regeneração após alterar qualquer parser ou especificação de comando e revise o diff do fragmento como parte da mudança. Os agentes que consomem <code>help --json</code> deveriam tratar a versão 1 do esquema como estável de forma aditiva: novos verbos, domínios ou campos podem aparecer sem aviso; as chaves existentes mantêm seu significado.</p>`,52)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};